const { STEPS, BUSINESS_TYPES, STAGES, SIZES, YEARS } = options;
const fmtScore = (v) => (v === null || v === undefined ? '판단 보류' : `${Math.round(v)}/100`);
const capText = (v) => (v === null || v === undefined ? '판단 보류(응답 부족)' : `${engineBand(v)}(${Math.round(v)}/100)`);
const STORAGE_KEY="beconic_tgn_v09";
function fresh(){return {step:0,visited:[0],mode:"quick",entry:"no-data",company:{name:"",stage:"소기업",roadmapField:"AI",bizType:"AI/SW 중심",sectorDetail:"",size:"1~9명",years:"1~3년",techKnow:"부분적으로 알고 있음",product:"",customer:""},discovery:{hardPart:"",automated:"",data:"",external:"",people:"",validation:""},inventory:[],answers:{},evidence:{},results:null,baseline:null}}
let state=fresh();
const $=id=>document.getElementById(id);
const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[m]));
const cname=c=>({tech:"기술성숙",rd:"R&D 역량",exec:"실행준비",evidence:"기술기록",scale:"확장준비",strategy:"전략정렬",risk:"리스크 대응"})[c]||c;
const profile=()=>engineProfile(state.company.bizType);
const deepQs=()=>deepQuestions(state.company.bizType);
const activeQs=()=>activeQuestions(state.mode,state.company.bizType);
function roadmapSelect(){return `<select id="roadmapField">${Object.entries(ROADMAP_GROUPS).map(([g,a])=>`<optgroup label="${g}">${a.map(x=>`<option ${x===state.company.roadmapField?"selected":""}>${x}</option>`).join("")}</optgroup>`).join("")}</select>`}
function seedInv(){if(state.inventory.length)return;const found=discoverCandidates(state);if(found.length>=2){state.inventory=ruleItems(found,1);return}let p=profile(),x=p==="제조"||p==="융합"?[["제품 설계·사양","설계기술"],["핵심 생산·공정","공정기술"],["품질검사·판정","품질기술"],["설비·장비/제어","생산기술"]]:p==="딥테크"?[["핵심 원리·원천기술","원천기술"],["시제품·실험 시스템","실증기술"],["핵심 소재·부품/알고리즘","핵심기술"],["Scale-up·적용기술","응용기술"]]:p==="서비스"?[["핵심 서비스 제공방식","서비스기술"],["운영 프로세스","운영기술"],["데이터 활용","데이터기술"],["외부 플랫폼 연계","통합기술"]]:[["제품/서비스 구현","응용기술"],["데이터 활용","데이터기술"],["AI·알고리즘/노하우","핵심기술"],["외부 솔루션 연계","통합기술"]];state.inventory=x.map((a,n)=>({id:n+1,name:a[0],type:a[1],ownership:"확인필요",status:"추정",critical:n<2,trl:0,confirmed:false,origin:"TEMPLATE"}))}
function syncBasic(){if(!$("companyName"))return;state.company={name:$("companyName").value.trim(),stage:$("companyStage").value,roadmapField:$("roadmapField").value,bizType:$("bizType").value,sectorDetail:$("sectorDetail").value.trim(),size:$("companySize").value,years:$("companyYears").value,techKnow:$("techKnow").value,product:$("product").value.trim(),customer:$("customer").value.trim(),elig:syncElig()}}
function syncDiscovery(){["hardPart","automated","data","external","people","validation"].forEach(k=>{let e=$("d_"+k);if(e)state.discovery[k]=e.value.trim()})}
function navTo(n){if(state.step===0)syncBasic();if(state.step===1)syncDiscovery();state.step=Math.max(0,Math.min(5,Number(n)));if(!state.visited.includes(state.step))state.visited.push(state.step);if(state.step>=2)seedInv();if(state.step===5)calc();render();window.scrollTo({top:0,behavior:"smooth"})}
function nav(){$("nav").innerHTML=STEPS.map((m,i)=>`<button class="navstep ${state.step===i?"active":""} ${state.visited.includes(i)&&i!==state.step?"visited":""}" onclick="navTo(${i})"><span class="num">${state.visited.includes(i)&&i<state.step?"✓":i+1}</span><span><strong>${m[0]}</strong><small>${m[1]}</small></span></button>`).join("");let p=Math.round(state.step/5*100);$("progBar").style.width=p+"%";$("progTxt").textContent=p+"%";$("heroStep").textContent=STEPS[state.step][0];$("heroSub").textContent=STEPS[state.step][1]}
// 이름표를 입력칸과 연결(스크린리더·이름표 클릭 시 입력칸 이동)
const forId=x=>{const m=/\bid="([^"]+)"/.exec(x);return m?` for="${m[1]}"`:""};
function field(l,x){return `<div class="field"><label${forId(x)}>${l}</label>${x}</div>`}
const EXAMPLE_BANK={};
function exampleBox(id,text){EXAMPLE_BANK[id]=text;return `<div class="example-box"><div class="example-head"><b>작성 예시</b><button type="button" class="example-use" onclick="applyExample('${id}')">예시 입력</button></div><div class="example-text" data-ex="${id}">${esc(text)}</div><div class="example-note">※ 예시는 참고용입니다. 자사 상황·수치·고객·기술명에 맞게 수정해 주세요.</div></div>`}
function fieldExample(l,x,id,example){return `<div class="field"><label${forId(x)}>${l}</label>${x}${exampleBox(id,example)}</div>`}
/** 운영유형을 바꾸면 1단계 작성 예시도 그 유형으로 */
function refreshExamples(){const c=document.getElementById("bizType");if(!c)return;state.company.bizType=c.value;["sectorDetail","product","customer"].forEach(k=>{EXAMPLE_BANK[k]=EX(k);const el=document.querySelector(`[data-ex="${k}"]`);if(el)el.textContent=EX(k)})}
if(typeof document!=="undefined")document.addEventListener("change",e=>{if(e.target&&e.target.id==="bizType")refreshExamples()});
function applyExample(id){let el=$(id),text=EXAMPLE_BANK[id];if(!el||!text)return;el.value=text;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));el.focus()}
function sel(id,a,v){return `<select id="${id}">${a.map(x=>`<option ${x===v?"selected":""}>${x}</option>`).join("")}</select>`}
function basic(){$("s0").innerHTML=`<div class="panel"><h2>1. 기업 이해</h2><p class="desc">기업규모와 기술로드맵 분야를 분리해 입력합니다. 산업분류와 운영유형을 분리한 이유는 같은 산업에서도 SW·제조·서비스형 진단문항이 달라지기 때문입니다.</p><div class="choice-row" style="margin-bottom:16px"><button class="choice ${state.entry==="no-data"?"active":""}" onclick="setEntry('no-data')">자료 없이 시작</button><button class="choice ${state.entry==="with-data"?"active":""}" onclick="setEntry('with-data')">자료와 함께 정밀진단</button><button class="choice ${state.entry==="delegate"?"active":""}" onclick="setEntry('delegate')">담당자 확인 중심</button></div><p class="subtle" style="margin:6px 0 10px">${state.entry==="with-data"?"정밀진단(업종 심화문항 포함)으로 진행합니다. 근거 자료를 옆에 두고 답하면 진단 신뢰도가 높아집니다.":state.entry==="delegate"?"대표님이 기본 정보를 적고, 기술 문항은 CTO·담당자와 함께 답하는 방식입니다. 모르는 문항은 '모름'으로 두고 넘어가세요.":"간편진단(12문항)으로 빠르게 시작합니다. 모르는 문항은 '모름'으로 두면 0점이 아니라 '확인 필요'로 처리됩니다."}</p><div class="grid two">${field("기업명",`<input id="companyName" value="${esc(state.company.name)}" placeholder="예: 비코닉랩">`)}${field("기업 단계",sel("companyStage",STAGES,state.company.stage))}${field("기술로드맵 기준 분야",roadmapSelect())}${field("기업 운영유형",sel("bizType",BUSINESS_TYPES,state.company.bizType))}${fieldExample("세부 업종·기술분야",`<input id="sectorDetail" value="${esc(state.company.sectorDetail)}" placeholder="예: 산업용 설비 예지보전 AI SaaS">`,"sectorDetail",EX("sectorDetail"))}${field("인원 규모",sel("companySize",SIZES,state.company.size))}${field("업력",sel("companyYears",YEARS,state.company.years))}${field("대표자의 자사 기술 이해도",sel("techKnow",["잘 알고 있음","부분적으로 알고 있음","거의 모름","담당자 확인 필요"],state.company.techKnow))}</div><div class="grid two" style="margin-top:13px">${fieldExample("주요 제품·서비스",`<textarea id="product" placeholder="제품·서비스가 무엇을 하고 어떤 결과를 제공하는지 적어주세요.">${esc(state.company.product)}</textarea>`,"product",EX("product"))}${fieldExample("주요 고객·사용자",`<textarea id="customer" placeholder="누가 사용하며 어떤 문제를 해결하려는지 적어주세요.">${esc(state.company.customer)}</textarea>`,"customer",EX("customer"))}</div>${eligHtml()}<div class="notice"><b>점수 원칙:</b> 기업단계·직원수·업력은 기술역량 점수에 직접 가산하지 않고, 기대수준과 해석문구를 조정하는 맥락변수로만 사용합니다. 규모가 크다고 기술점수가 자동으로 높아지지 않습니다.</div><h3 style="margin-top:16px">사용법 · 활용법</h3><div class="usage-guide"><div class="usage-step"><b>1. 사업언어로 입력</b><p>전문기술명을 몰라도 제품·고객·문제·현장 경험을 적으면 됩니다.</p></div><div class="usage-step"><b>2. 핵심기술 확인</b><p>자동 생성된 기술후보 중 사업성과를 좌우하는 기술만 핵심으로 지정합니다.</p></div><div class="usage-step"><b>3. 결과를 실행에 활용</b><p>진단결과를 R&D 계획, 기술문서, 지원사업 준비, 내부 회의, 멘토링에 사용합니다.</p></div></div><div class="usage-callout"><b>권장 활용:</b> 1차 자가진단 → CTO/기술담당자 확인 → 필요한 Evidence 보완 → 90일 실행 → 재진단. 처음부터 모든 자료를 준비할 필요는 없습니다.</div><div class="actions"><span></span><button class="btn primary" onclick="navTo(1)">기술 발견 시작 →</button></div></div>`}
const ELIG_FIELDS=[["lab","연구전담조직",["연구소","전담부서","없음"]],["researchers","연구 인력",["0명","1~2명","3~5명","6명 이상"]],["tax","국세·지방세 체납",["없음","있음"]],["default","채무불이행·부실",["없음","있음"]],["restriction","정부 R&D 참여제한",["없음","있음"]],["ongoing","수행 중인 정부과제",["0건","1건","2건","3건 이상"]],["cofund","자부담 마련",["가능","일부 가능","어려움"]],["certs","벤처·이노비즈 등 인증",["없음","벤처","이노비즈·메인비즈","벤처+이노비즈 등 복수"]]];
/** 지원사업 공통 자격 확인(선택) — 점수에 쓰지 않고 신청 준비도에만, AI에는 보내지 않음 */
function eligHtml(){const e=state.company.elig||{},n=ELIG_FIELDS.filter(f=>e[f[0]]).length;return `<details class="elig-box"${n?" open":""}><summary><b>지원사업 자격 확인(선택)</b> <span class="subtle">R&D·기술바우처 신청 준비도 진단에만 씁니다 · 점수에 반영하지 않고 AI로 보내지 않습니다 · ${n}/${ELIG_FIELDS.length} 입력</span></summary><div class="grid two" style="margin-top:10px">${ELIG_FIELDS.map(f=>field(f[1],`<select id="elig_${f[0]}"><option value="">선택 안 함</option>${f[2].map(o=>`<option ${e[f[0]]===o?"selected":""}>${o}</option>`).join("")}</select>`)).join("")}</div></details>`}
function syncElig(){if(!$("elig_lab"))return state.company.elig||{};return Object.fromEntries(ELIG_FIELDS.map(f=>[f[0],$("elig_"+f[0]).value]).filter(x=>x[1]))}
function setEntry(v){syncBasic();state.entry=v;state.mode=v==="with-data"?"deep":"quick";basic()}
/** 작성 예시: 기업 운영유형별(src/app/examples.ts) */
const EX=k=>examplesFor(state.company.bizType)[k]||"";
function discField(k,l,p){return fieldExample(l,`<textarea id="d_${k}" placeholder="${p}">${esc(state.discovery[k])}</textarea>`,`d_${k}`,EX(k))}
function discovery(){$("s1").innerHTML=`<div class="panel"><h2>2. 기술 발견</h2><p class="desc">기술 이름을 몰라도 답할 수 있는 질문으로 우리 회사의 기술 후보를 찾습니다. 각 문항의 '작성 예시'를 참고해 자사 상황에 맞게 적어 주세요.</p><div class="grid two">${discField("hardPart","경쟁사가 따라 하기 가장 어려운 부분","제품설계, 공정, 데이터, 알고리즘, 노하우 등")}${discField("automated","사람 대신 자동으로 판단·처리되는 부분","예측, 추천, 검사, 제어, 품질판정 등")}${discField("data","계속 쌓이는 데이터","고객, 생산, 센서, 이미지, 로그, 거래 등")}${discField("external","외부에 의존하는 부분","외주개발, LLM API, 클라우드, 장비, 공급사 등")}${discField("people","기술을 가장 잘 아는 사람","CTO, 개발자, 생산책임자, 연구소장, 외주사 등")}${discField("validation","외부에서 실제 확인된 경험","PoC, 판매, 납품, 시험, 인증, 특허 등")}</div><div class="notice"><b>작성 팁:</b> 가능한 경우 “무엇을·누가·어디서·얼마나·어떤 결과로”까지 적어주세요. 수치와 기간, 실제 고객·현장 검증 여부가 포함되면 진단 정확도가 높아집니다.</div><div class="actions"><button class="btn" onclick="navTo(0)">← 이전</button><button class="btn primary" onclick="makeInv()">기술 후보 생성 →</button></div></div>`}
function makeInv(){syncDiscovery();state.inventory=[];discState={status:"idle",data:null,key:""};seedInv();if(state.inventory.every(t=>!t.basis)&&state.discovery.hardPart)state.inventory.unshift({id:99,basis:state.discovery.hardPart,name:clipS(state.discovery.hardPart,40),type:"핵심 차별기술 후보",ownership:"자체 가능",status:"대표진술",critical:true,trl:0,confirmed:false});navTo(2)}
function inlineSel(a,v,on,label){return `<select onchange="${on}"${label?` aria-label="${label}"`:""}>${a.map(x=>`<option ${x===v?"selected":""}>${x}</option>`).join("")}</select>`}
function trlSel(v,on){return `<select onchange="${on}" aria-label="TRL(기술성숙도)"><option value="0" ${!v?"selected":""}>TRL 확인 필요</option>${[1,2,3,4,5,6,7,8,9].map(n=>`<option value="${n}" ${v===n?"selected":""}>TRL ${n} · ${TRL_LEVELS[n]}</option>`).join("")}</select>`}
function inv(){seedInv();$("s2").innerHTML=`<div class="panel"><h2>3. 핵심기술 식별</h2><p class="desc">기업 전체에 TRL 하나를 붙이지 않고, 사업성과와 제품성능을 좌우하는 핵심기술별로 현재 수준을 확인합니다. 기술 발견 답변에서 찾은 후보는 '추정' 상태로 시작하니 이름·보유형태·TRL을 확인해 주세요.</p><div class="disc-panel" data-disc>${discHtml()}</div>${reflectNotice()}<div class="tech-list">${state.inventory.map((t,i)=>`<div class="tech-row"><div class="tech-title"><b>${esc(t.name)}</b><small>${esc(t.type)}${t.origin==="AI"?' · <span class="tag info">AI 추천</span>':t.origin==="TEMPLATE"?' · <span class="tag warn">업종 기본 예시 — 실제 기술명으로 바꿔 주세요</span>':t.basis?' · 답변에서 찾음':""}</small>${t.basis?`<span class="tech-basis" data-raw>근거: “${esc(clipS(t.basis,70))}”</span>`:""}<label class="check"><input type="checkbox" ${t.critical?"checked":""} onchange="setInv(${i},'critical',this.checked);inv()"> 핵심기술 <span class="tag ${t.critical?"ok":""}">${t.critical?"결과 반영":"목록만"}</span></label></div>${inlineSel(["자체","외부","혼합","확인필요","자체 가능"],t.ownership,`setInv(${i},'ownership',this.value)`,"보유형태")}${inlineSel(["확정","대표진술","추정","미확인"],t.status,`setInv(${i},'status',this.value)`,"확인 상태")}${trlSel(t.trl,`setInv(${i},'trl',Number(this.value))`)}<div class="tech-ops"><button class="btn ${t.confirmed?"soft":""}" onclick="toggleInv(${i})">${t.confirmed?"✓ 확인":"내용 확인"}</button><button class="linkbtn" onclick="removeInv(${i})" aria-label="${esc(t.name)} 삭제">삭제</button></div></div>`).join("")}</div><div class="notice"><b>핵심 원칙:</b> TRL은 기술성숙도이고, 회사규모·매출·시장성·증빙신뢰도와 분리합니다.</div><div class="actions"><button class="btn" onclick="navTo(1)">← 이전</button><button class="btn primary" onclick="navTo(3)">핵심진단 →</button></div></div>`}
function reflectNotice(){const n=state.inventory.filter(t=>t.critical&&String(t.name).trim()).length,m=state.inventory.length;return `<div class="notice reflect-note"><b>결과 반영 기준:</b> 6단계 결과·PDF(TRL·로드맵 대조·R&D 과제·리스크)에는 <b>'핵심기술'에 체크한 기술만</b> 들어갑니다. 지금 ${m}개 중 <b>${n}개</b> 반영${n>6?" — 6개 이하로 줄이면 보고서가 더 선명해집니다":n===0?" — 1개 이상 체크해 주세요":""}.</div>`}
function setInv(i,k,v){state.inventory[i][k]=v;if(k==="name")state.inventory[i].origin=state.inventory[i].origin==="TEMPLATE"?"":state.inventory[i].origin}function removeInv(i){const t=state.inventory[i];if(!t||!confirm(`'${t.name}'을(를) 목록에서 지울까요?`))return;state.inventory.splice(i,1);inv()}function toggleInv(i){state.inventory[i].confirmed=!state.inventory[i].confirmed;inv()}
function qhtml(q,i){let a=ANCHORS[q.cat];return `<div class="q"><div class="qhead"><div class="qtitle">${i+1}. ${q.t}</div><div class="qmeta">${cname(q.cat)}${q.critical?" · 핵심":""}</div></div><div class="scale5">${a.map((x,n)=>`<button class="${state.answers[q.id]===n+1?"selected":""}" onclick="ans('${q.id}',${n+1})"><b>${n+1}</b><br>${x}</button>`).join("")}</div><div class="unknown-row"><span class="hint">현재 상태와 가장 가까운 행동·운영 수준을 선택하세요.</span><button class="unknown ${state.answers[q.id]===null?"selected":""}" onclick="ans('${q.id}',null)">? 모름·확인필요</button></div></div>`}
function diagnosis(){let qs=activeQs(),core=qs.filter(q=>q.id[0]==="q"),deep=qs.filter(q=>q.id[0]==="d");$("s3").innerHTML=`<div class="panel"><h2>4. 핵심진단</h2><p class="desc">기본 12문항으로 먼저 진단하고 필요한 경우에만 기업 운영유형에 맞는 심화문항을 추가합니다.</p><div class="choice-row" style="margin-bottom:14px"><button class="choice ${state.mode==="quick"?"active":""}" onclick="setMode('quick')">간편 · 12문항</button><button class="choice ${state.mode==="deep"?"active":""}" onclick="setMode('deep')">정밀 · ${12+deepQs().length}문항</button></div><div class="module-head"><h3>공통 핵심진단</h3><span>기술·R&D·실행·확장·전략·리스크</span></div><div class="qwrap">${core.map((q,i)=>qhtml(q,i)).join("")}</div>${state.mode==="deep"&&deep.length?`<div class="module-head"><h3>${esc(state.company.bizType)} 심화</h3><span>선택형</span></div><div class="qwrap">${deep.map((q,i)=>qhtml(q,core.length+i)).join("")}</div>`:""}<div class="notice">“모름”은 0점이 아닙니다. 미확인 상태로 남기고 근거 확인·진단 신뢰도에 반영합니다.</div><div class="actions"><button class="btn" onclick="navTo(2)">← 이전</button><button class="btn primary" onclick="navTo(4)">근거 확인 →</button></div></div>`}
function setMode(v){state.mode=v;diagnosis()}function ans(id,v){state.answers[id]=v;diagnosis()}
const ev=id=>evidenceLevel(state.evidence,id);
function answerLabel(q){let v=state.answers[q.id];return v===null||v===undefined?"모름·확인필요":ANCHORS[q.cat][v-1]}
function evidenceReason(q){let v=state.answers[q.id];if(v===null||v===undefined)return "모름·확인필요";if(q.critical)return "핵심판단 검증";if(v>=4)return "높은 자기평가 검증";return "선별 확인"}
function evidenceCandidates(){let qs=activeQs();return qs.filter(q=>{let v=state.answers[q.id];return q.critical||v===null||v===undefined||v>=4}).sort((a,b)=>{let av=(state.answers[a.id]===null||state.answers[a.id]===undefined)?3:(a.critical?2:1),bv=(state.answers[b.id]===null||state.answers[b.id]===undefined)?3:(b.critical?2:1);return bv-av}).slice(0,6)}
function evidence(){let qs=evidenceCandidates();$("s4").innerHTML=`<div class="panel"><h2>5. 근거 확인</h2><p class="desc">이 단계는 기술점수를 다시 매기는 단계가 아니라, <b>현재 판단을 얼마나 믿을 수 있는지 확인하는 단계</b>입니다. 최대 6개 핵심 항목만 확인합니다.</p><div class="evidence-help"><div class="mini"><strong>“모름·확인필요”의 뜻</strong><p>기술이 없다는 뜻이 아닙니다. 현재 응답자가 판단할 정보가 부족하다는 뜻입니다.</p></div><div class="mini"><strong>진단에는 어떻게 반영?</strong><p>해당 문항을 0점 처리하지 않고, 기술점수 산정에서 제외하거나 보수적으로 처리하며 진단 신뢰도를 낮춥니다.</p></div><div class="mini"><strong>그 다음에는?</strong><p>CTO·개발·생산담당자 확인 또는 최소 자료를 확보하도록 결과의 Next Best Evidence에 표시합니다.</p></div></div><div class="notice"><b>활용 예:</b> 대표가 “실제환경 검증 여부를 모름”이라고 답했다면 낮은 기술점수를 주는 대신, “기술수준 미확정 → PoC 결과·운영로그 확인 필요”로 처리합니다.</div>${qs.map((q,i)=>`<div class="ev-card"><div class="ev-head"><b>${i+1}. ${q.t}<span class="reason-chip">${evidenceReason(q)}</span></b><span>진단응답: ${answerLabel(q)}</span></div><div class="evidence">${EVIDENCE.map(e=>`<button class="epill ${Number(state.evidence[q.id]??0)===e.k?"selected":""}" onclick="setEv('${q.id}',${e.k})">${e.name}</button>`).join("")}</div><div class="anchor">${ev(q.id).desc}</div></div>`).join("")}<div class="actions"><button class="btn" onclick="navTo(3)">← 이전</button><button class="btn primary" onclick="navTo(5)">통합 진단결과 생성 →</button></div></div>`}
