function discPayload(){const c=state.company,d=state.discovery;return {task:"discover",consent:true,input:{company:{bizType:clipS(c.bizType,60),roadmapField:clipS(c.roadmapField,60),sectorDetail:clipS(c.sectorDetail,300),product:clipS(c.product,600)},discovery:Object.fromEntries(["hardPart","automated","data","external","validation"].map(k=>[k,clipS(d[k],600)])),existing:state.inventory.slice(0,20).map(t=>clipS(t.name,120))}}}
