function discHtml(){const rule=`<button class="btn" onclick="ruleRediscover()">답변으로 후보 다시 찾기</button>`;if(!AI_ON)return `<div class="disc-head"><b>기술 후보 찾기</b><span class="subtle">2단계 답변의 핵심 표현으로 후보를 찾았습니다(외부 전송 없음).</span>${rule}</div>`;
 if(!aiConsented())return `<div class="disc-head"><b>AI로 기술 후보 더 찾기</b><span class="subtle">2단계 답변과 제품 설명(기업명 제외)을 해외 AI 서비스(Anthropic, 미국)로 보내 이미 가진 기술을 찾습니다. AI가 고른 후보는 답변 원문 구절을 근거로 붙이고, 확인을 눌러야 목록에 들어갑니다.${aiConsent()==="decline"?" 지금은 'AI 사용 안 함'으로 선택되어 있습니다.":""}</span><div class="disc-actions"><button class="btn primary" onclick="agreeDiscover()">동의하고 AI로 찾기</button>${rule}</div></div>`;
 const s=discState.status;if(s==="loading")return `<div class="disc-head"><b>AI가 답변을 읽고 기술 후보를 찾는 중입니다</b><span class="subtle">보통 10~30초 걸립니다. 그동안 아래 목록을 확인하셔도 됩니다.</span></div>`;
 if(s==="ok"){const cs=discState.data.candidates;return `<div class="disc-head"><b>AI가 찾은 기술 후보 ${cs.length}개</b><span class="subtle">답변 원문 구절을 근거로 찾았습니다. 맞는 것만 '목록에 추가'하세요(추가 후에도 이름·TRL을 고칠 수 있습니다).</span><div class="disc-actions"><button class="btn" onclick="addAllDisc()">남은 후보 모두 추가</button><button class="btn" onclick="runDiscover()">다시 찾기</button></div></div><div class="disc-list">${cs.map((c,i)=>`<div class="disc-card ${c.state}"><div class="disc-top"><b>${esc(c.name)}</b><span class="tag">${esc(c.type)}</span><span class="tag">${esc(c.ownership)}</span></div><p class="disc-quote" data-raw>“${esc(c.quote)}” <small>${esc(c.fieldLabel)}</small></p><p class="subtle">${esc(c.why)}</p><div class="disc-actions">${c.state==="core"?'<span class="tag ok">핵심기술로 추가됨 · 결과 반영</span>':c.state==="added"?'<span class="tag ok">목록에 추가됨</span> <span class="subtle">결과에 넣으려면 아래 목록에서 \'핵심기술\' 체크</span>':c.state==="skipped"?'<span class="tag">제외함</span>':`<button class="btn primary" onclick="addDisc(${i})">목록에 추가</button><button class="btn" onclick="skipDisc(${i})">제외</button>`}</div></div>`).join("")}</div>`}
 const msg=s==="not_configured"?"AI 기능이 아직 연결되지 않았습니다.":s==="fallback"?"이번 답변으로는 AI가 근거 있는 후보를 찾지 못했습니다. 답변을 조금 더 구체적으로 적어 보세요.":s==="error"?"AI 서버에 연결하지 못했습니다. 잠시 후 다시 시도해 주세요.":"2단계 답변을 바탕으로 이미 가진 기술을 AI가 찾아 드립니다.";
 return `<div class="disc-head"><b>AI로 기술 후보 더 찾기</b><span class="subtle">${msg}</span><div class="disc-actions"><button class="btn primary" onclick="runDiscover()">AI로 기술 후보 찾기</button>${rule}</div></div>`}
function aiConsent(){if(consentMem!==null)return consentMem;try{const v=JSON.parse(localStorage.getItem(CONSENT_KEY)||"null");consentMem=v&&v.version===CONSENT_VERSION?v.choice:null}catch{consentMem=null}return consentMem}
