function loadAi(matches){if(!AI_ON||!state.results||state.results.insufficient||!aiConsented())return;const body=aiPayload(matches),key=JSON.stringify(body);if(aiState.key===key&&aiState.status!=="error")return;aiState={key,status:"loading",data:null};setTimeout(()=>{document.querySelectorAll("[data-ai]").forEach(el=>{el.innerHTML=aiHtml()});updateStatus()},0);const until=Date.now()+180000,get=u=>fetch(u,{cache:"no-store"}).then(r=>r.ok||r.status===202?r.json():{status:"error"}).catch(()=>({status:"error"})),wait=ms=>new Promise(r=>setTimeout(r,ms));
 aiPending=fetch("/api/ai-interpret",{method:"POST",headers:{"content-type":"application/json"},body:key}).then(r=>r.ok||r.status===202?r.json():{status:"error"}).catch(()=>({status:"error"})).then(async j=>{while((j.status==="queued"||j.status==="running")&&j.job!==null&&aiState.key===key){if(Date.now()>until){j={status:"fallback",reason:"timeout"};break}const id=j.job||aiState.job;aiState.job=id;await wait(3000);j={...(await get(`/api/ai-interpret?job=${encodeURIComponent(id)}`)),job:id}}return j}).then(j=>{if(aiState.key!==key)return;aiState={key,status:j.status||"error",data:j};document.querySelectorAll("[data-ai]").forEach(el=>{el.innerHTML=aiHtml()});refreshAiSlots();updateStatus();buildPrintReport()})}
