const prClipSentence=(t,n)=>{t=String(t??"");if(t.length<=n)return t;const cut=t.slice(0,n),m=[...cut.matchAll(/(다|요)?\.(\s|$)/g)].pop();return m&&m.index>n*0.4?cut.slice(0,m.index+m[0].trimEnd().length):prClip(t,n)};
