 const rows=[["green","규칙 엔진","정상","점수·TRL·우선순위 계산(브라우저)"],roadmapIndexReady()?["green","로드맵 색인","정상","52개 문서 원문 색인(전략품목·핵심기술·쪽)"]:["yellow","로드맵 색인","불러오는 중","원문 색인을 불러오는 동안 세부분야 목록으로 표시"]];
