 let ai;if(!AI_ON)ai=["gray","꺼짐","화면 스위치(VITE_AI_INTERPRET) 꺼짐"];else if(!aiConsented())ai=["gray",aiConsent()==="decline"?"사용 안 함":"동의 전",aiConsent()==="decline"?"사용자가 AI 해석을 사용하지 않도록 선택":"결과 화면의 외부 처리 안내에 동의하면 실행"];else if(aiState.status==="ok")ai=["green","정상",`이번 진단 해석 완료(${aiState.data.model})`];else if(aiState.status==="loading")ai=["wait","해석 중","Claude가 이번 진단을 해석하는 중(30초~1분)"];else if(aiState.status==="fallback")ai=["yellow","대체 동작",`이번 진단은 규칙 기반 해석으로 표시(${aiState.data&&aiState.data.reason||"사유 미상"})`];else if(aiState.status==="error")ai=["red","오류","이번 진단의 AI 해석 서버 연결 실패"];else if(aiState.status==="not_configured")ai=["gray","미설정","서버에 Claude API 키 미설정"];else ai=srv("claude",["gray","대기","결과 화면에서 해석합니다"]);
