// 원문 근거 조회: 서버 오류(콜드 스타트 등)는 2초 뒤 1회 재시도, 그래도 실패하면 'error'(결과 화면을 다시 열면 재시도)
function loadEvidence(matches){if(!EVIDENCE_ON)return;const uids=matches.map(m=>m.uid).filter(Boolean);if(!uids.length)return;const key=evidenceQuery()+"|"+uids.join(",")+"|"+(aiConsented()?"ext":"kw");if(rmEvidence.key===key&&rmEvidence.status!=="error")return;rmEvidence={key,items:{},status:"loading"};const refresh=()=>{document.querySelectorAll("[data-ev-uid]").forEach(el=>{el.innerHTML=evidenceHtml(el.getAttribute("data-ev-uid"))});document.querySelectorAll("[data-ev-note]").forEach(el=>{el.innerHTML=evidenceNote()});updateStatus()};setTimeout(refresh,0);const once=()=>fetch("/api/roadmap-evidence",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({query:evidenceQuery(),itemUids:uids,external:aiConsented()})}).then(r=>r.ok?r.json():{status:"error"}).catch(()=>({status:"error"}));evPending=once().then(j=>j.status==="error"?new Promise(r=>setTimeout(r,2000)).then(once):j).then(j=>{if(rmEvidence.key!==key)return;rmEvidence={key,items:j.status==="ok"?j.items:{},status:j.status==="ok"?"ok":j.status==="error"?"error":"off",mode:j.mode};refresh();buildPrintReport()})}
