const lvl=v=>v===null?"확인 필요":LEVEL_NAME[v],lvlS=v=>v===null?"?":LEVEL_NAME[v].charAt(0);
function riskHtml(rt){const top=rt.risks.slice(0,3),c=rt.counts;return `<div class="rt-top"><div class="viz"><h3>리스크 히트맵</h3><p>가로는 발생 가능성, 세로는 영향입니다. 점은 리스크 ID이며, 회색 칸은 관련 문항이 '모름'이라 가능성을 판단하지 않은 리스크입니다.</p>${riskHeatmapSVG(rt.risks)}</div><div class="viz"><h3>리스크 요약</h3><div class="rt-counts"><span class="tag bad">높음 ${c.high}</span><span class="tag warn">중간 ${c.mid}</span><span class="tag ok">낮음 ${c.low}</span><span class="tag">확인 필요 ${c.unknown}</span></div><h3 style="margin-top:12px">최우선 관리 리스크</h3><ol class="ask-list">${top.map(x=>`<li><b>${x.id} ${esc(x.name)}</b> <span class="tag ${gradeCls(x.grade)}">${x.grade}</span><br><span class="subtle">${esc(x.scenario)}</span></li>`).join("")}</ol></div></div>
 <h3 style="margin-top:16px">리스크 레지스터</h3><div class="tablewrap"><table class="rt-table"><thead><tr><th>ID</th><th>리스크 · 시나리오</th><th>판단 근거</th><th>가능성</th><th>영향</th><th>등급</th><th>조기경보 신호</th><th>90일 완화조치</th><th>책임</th></tr></thead><tbody>${rt.risks.map(x=>`<tr><td><b>${x.id}</b></td><td><b>${esc(x.name)}</b><br><span class="subtle">${esc(x.scenario)}</span></td><td class="subtle">${esc(x.basis)}</td><td>${lvl(x.likelihood)}</td><td>${lvl(x.impact)}</td><td><span class="tag ${gradeCls(x.grade)}">${x.grade}</span></td><td>${esc(x.earlyWarning)}</td><td>${esc(x.mitigation)}</td><td>${esc(x.owner)}</td></tr>`).join("")}</tbody></table></div>
 <div class="rt-grid2"><div class="ai-card"><h4>이 진단이 틀릴 수 있는 지점</h4><ul class="ai-list">${rt.diagnostic.map(d=>`<li><span class="tag ${d.level==="주의"?"bad":d.level==="확인"?"warn":""}">${d.level}</span> <b>${esc(d.title)}</b> ${esc(d.detail)}</li>`).join("")}</ul></div><div class="ai-card"><h4>레드팀 반증 질문</h4><p class="subtle" style="margin:0 0 8px">경영회의에서 아래 질문에 근거로 답하지 못하면 해당 리스크는 '높음'으로 관리하세요.</p><ol class="ask-list">${rt.risks.slice(0,6).map(x=>`<li><b>${x.id}</b> ${esc(x.challenge)}</li>`).join("")}</ol></div></div>`}
function kpi(n,v,note){if(v===null||v===undefined)return `<div class="score-card"><small>${n}</small><strong>—</strong><span>판단 보류</span></div>`;v=Math.round(v);return `<div class="score-card"><small>${n}</small><strong>${v}<span style="font-size:12px">/100</span></strong><span>${note??band(v)}</span></div>`}
function radarSVG(m){let data=AREAS({m}),cx=150,cy=150,R=100,n=data.length,ang=i=>-Math.PI/2+i*2*Math.PI/n,pt=(i,r)=>[cx+Math.cos(ang(i))*R*r,cy+Math.sin(ang(i))*R*r],pts=r=>data.map((d,i)=>pt(i,r).join(",")).join(" "),val=d=>d[1]===null?0:d[1]/100,poly=data.map((d,i)=>pt(i,val(d)).join(",")).join(" ");let axes=data.map((d,i)=>{let [x,y]=pt(i,1),[lx,ly]=pt(i,1.3),c=Math.cos(ang(i)),anchor=Math.abs(c)<.2?"middle":c>0?"start":"end",dy=Math.sin(ang(i))<-.5?-6:0;return`<line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}" stroke="#d0d5dd"/><text x="${lx}" y="${ly+dy}" text-anchor="${anchor}" font-size="11" fill="#475467">${d[0]}</text><text data-ckradar="${d[0]}" x="${lx}" y="${ly+dy+14}" text-anchor="${anchor}" font-size="14" font-weight="700" fill="${d[1]===null?"#98a2b3":d[1]<45?"#b42318":d[1]<65?"#b54708":"#1d3a8a"}">${d[1]===null?"보류":Math.round(d[1])}</text>`}).join(""),dots=data.map((d,i)=>d[1]===null?"":`<circle cx="${pt(i,val(d))[0]}" cy="${pt(i,val(d))[1]}" r="3" fill="#4f66b0"/>`).join("");return`<svg viewBox="-28 -8 356 322" width="100%" role="img" aria-label="7개 영역 점수 레이더"><polygon points="${pts(.25)}" fill="none" stroke="#e4e7ec"/><polygon points="${pts(.5)}" fill="none" stroke="#e4e7ec"/><polygon points="${pts(.75)}" fill="none" stroke="#e4e7ec"/><polygon points="${pts(1)}" fill="none" stroke="#d0d5dd"/><text x="${cx+3}" y="${cy-R*.5+3}" font-size="8" fill="#98a2b3">50</text><text x="${cx+3}" y="${cy-R+3}" font-size="8" fill="#98a2b3">100</text>${axes}<polygon points="${poly}" fill="rgba(79,102,176,.16)" stroke="#4f66b0" stroke-width="2"/>${dots}</svg>`}
function bars(g){return`<div class="bars">${g.map(x=>`<div class="barrow"><b>${x.area}</b><div class="bartrack"><i style="width:${x.score}%"></i></div><span>${x.score}</span></div>`).join("")}</div>`}
function phase(t,sub,a){return`<div class="phase"><span class="tag">${sub}</span><h3>${t}</h3>${a.length?`<ul>${a.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`:`<p class="hint">추가 과제 도출 필요</p>`}</div>`}
function gapText(a,s){let low=s<45,mid=s<65,map={"기술성숙":low?"실제환경 검증과 성공기준 정의가 우선입니다.":mid?"반복검증과 제품화 기준 보완이 필요합니다.":"기술고도화 단계입니다.","R&D 역량":low?"R&D 자원·활동·성과 연결이 부족합니다.":mid?"R&D 관리·성과측정 표준화가 필요합니다.":"R&D 체계가 비교적 안정적입니다.","실행준비":low?"담당·일정·완료기준이 불명확합니다.":mid?"과제관리 체계 보완이 필요합니다.":"실행체계가 안정적입니다.","기술기록":low?"기술을 설명·검증할 근거가 부족합니다.":mid?"핵심 기록 표준화가 필요합니다.":"대외검증 준비도가 높습니다.","확장준비":low?"성장 시 병목 가능성이 큽니다.":mid?"확장 기준과 검증이 필요합니다.":"확장 준비도가 양호합니다.","전략정렬":low?"시장·정책·산업방향과 기술계획 연결이 부족합니다.":mid?"R&D·IP·인증과 기술계획 연결을 구체화해야 합니다.":"전략 방향과 연계 가능성이 높습니다.","리스크대응":low?"외부의존·인력·규제 대응이 우선입니다.":mid?"대응책 구체화가 필요합니다.":"리스크 관리 준비도가 양호합니다."};return map[a]||"응답 근거가 부족해 점수를 산정하지 않았습니다. 담당자 확인이 우선입니다."}

