  html+=prPage(pg(),'Executive Summary',`<div class="pr-kicker">Executive Summary</div><h2 class="pr-title">경영진 의사결정 요약</h2><p class="pr-subtitle">점수보다 병목, 신뢰도, 우선 행동과 기대효과를 중심으로 해석합니다. 모든 수치는 응답자 자가진단 기준이며 외부 검증 전입니다.</p><div class="pr-decision" data-ck="summary" data-p0area="${esc(primary.area)}" data-p0act="${esc(pact[0])}" data-toptech="${crit[0]?esc(crit[0].name):""}"><p>현재 기술역량은 <b>${capText(r.capability)}</b> 수준으로 추정됩니다. ${summaryLine(r,dims,primary,pact,crit[0],"b")} 진단 신뢰도는 <b>${Math.round(r.confidence)}/100</b>으로 ${r.confidence<60?'현재 기술수준보다 먼저 핵심 Evidence와 담당자 확인을 보강해야 합니다.':'현재 결과를 실행계획 기준선으로 활용할 수 있으나 핵심기술별 KPI·Evidence를 병행 관리해야 합니다.'}</p></div><div class="pr-grid4">${prMetric('기술역량',r.capability)}${prMetric('진단 신뢰도',r.confidence,r.level)}${prMetric('최강 영역',dims.strong[0][1],dims.strong[0][0])}${prMetric('최약 영역',dims.weak[0][1],dims.weak[0][0])}</div><div class="pr-divider"></div><div class="pr-grid2"><div class="pr-card soft"><h4>핵심 강점</h4><ul>${dims.strong[0][1]===null?"<li>응답이 부족해 영역별 점수를 산정하지 않았습니다. 핵심 문항 응답과 담당자 확인 후 재진단하면 강점·병목을 제시합니다.</li>":dims.strong.map(x=>`<li><b>${x[0]}</b> ${fmtScore(x[1])} - ${dimensionDetail(x[0],x[1]).interpret}</li>`).join('')}</ul></div><div class="pr-card warn"><h4>우선 개선</h4><ul>${byPriority(r.gaps).slice(0,3).map(g=>`<li><b>[${g.priority}] ${g.area}</b> ${fmtScore(g.score)} - ${gapText(g.area,g.score)}</li>`).join('')}</ul></div></div><div class="pr-callout"><b>경영진 권고:</b> P0 과제를 별도 프로젝트로 지정하고 Owner·Due Date·KPI·Evidence를 100% 연결한 뒤 90일 후 동일 기준으로 재진단하십시오.</div><div class="pr-grid2 pr-position"><div class="pr-card"><h4>역량 × 진단 신뢰도 위치</h4>${positionMatrixSVG(r.capability,r.confidence)}</div><div class="pr-card soft"><h4>${quad?`현재 위치 · ${quad.label}`:"현재 위치 · 판단 보류"}</h4><p>${quad?quad.meaning:"기술역량을 산정할 응답이 부족해 위치를 표시하지 않았습니다."}</p>${aiOk()&&aiState.data.interpretation.headline?`<p class="pr-ai-line"><span class="pr-source">AI 해석 요지(Claude)</span> ${esc(prClipSentence(aiState.data.interpretation.headline,220))}</p>`:""}<h4 style="margin-top:3mm">의사결정 요청</h4><ol class="pr-asks">${decisionAsks(r).map(x=>`<li>${esc(x)}</li>`).join("")}</ol></div></div>`,total);

  if(dl){const dm=(n,x)=>`<div class="pr-metric"><small>${n}</small><strong>${x.prev??"—"}→${x.cur??"—"}</strong><span>${x.diff===null?x.verdict:`${sgn(x.diff)} · ${x.verdict}`}</span></div>`,rc=dl.risks.filter(x=>x.change!=="유지");html+=prPage(pg(),'Re-diagnosis Delta',`<div class="pr-kicker">Re-diagnosis Delta</div><h2 class="pr-h2">재진단 비교 · 기준 진단 대비 변화</h2><p class="pr-lead">기준 진단(${fmtD(dl.from)})의 입력을 현재 기준으로 다시 계산해 같은 잣대로 비교했습니다. ±${dl.margin}점 안의 변화는 오차 범위로 봅니다.${dl.versionNote||dl.modeNote?` ${esc([dl.versionNote,dl.modeNote].filter(Boolean).join(" "))}`:""}</p><div class="pr-decision"><p>${esc(dl.headline)}</p></div><div class="pr-grid4">${dm("기술역량",dl.capability)}${dm("진단 신뢰도",dl.confidence)}<div class="pr-metric"><small>진단 단계</small><strong style="font-size:11pt">${dl.level.prev===dl.level.cur?dl.level.cur:`${dl.level.prev}→${dl.level.cur}`}</strong><span>${dl.level.prev===dl.level.cur?"유지":"변경"}</span></div><div class="pr-metric"><small>모름·미응답</small><strong>${dl.unknown.prev}→${dl.unknown.cur}</strong><span>'높음' 리스크 ${dl.riskCounts.prevHigh}→${dl.riskCounts.curHigh}</span></div></div><div class="pr-grid2" style="margin-top:3mm"><div class="pr-card"><h4>영역별 변화 <span class="pr-source">회색 기준 · 파랑 개선 · 빨강 악화</span></h4>${deltaDumbbellSVG(dl.dims.map(x=>({label:x.area,prev:x.prev,cur:x.cur,verdict:x.verdict})))}</div><div class="pr-card"><h4>기준 P0·P1 과제 이행 결과</h4><table class="pr-table compact"><thead><tr><th>영역</th><th>기준</th><th>이번</th><th>결과</th></tr></thead><tbody>${dl.priorities.map(p=>`<tr><td><b>${p.area}</b></td><td>${p.prevPriority} · ${p.prevScore??"보류"}</td><td>${p.curPriority??"우선순위 밖"} · ${p.curScore??"보류"}</td><td><span class="pr-pill ${vCls(p.outcome)}">${p.outcome}</span></td></tr>`).join("")||`<tr><td colspan="4">기준 P0·P1 없음</td></tr>`}</tbody></table></div></div><div class="pr-grid2" style="margin-top:3mm"><div class="pr-card soft"><h4>핵심기술 TRL 변화</h4><ul>${dl.trl.slice(0,6).map(t=>`<li><b>${esc(prClip(t.name,24))}</b> ${t.prev?`TRL ${t.prev}`:"확인 필요"} → ${t.cur?`TRL ${t.cur}`:"확인 필요"} (${t.status})</li>`).join("")||"<li>핵심기술 미지정</li>"}</ul></div><div class="pr-card warn"><h4>리스크 등급 변화</h4><ul>${rc.slice(0,6).map(x=>`<li><b>${x.id} ${esc(x.name)}</b> ${x.prev??"—"} → ${x.cur??"—"} (${x.change})</li>`).join("")||"<li>등급이 바뀐 리스크 없음</li>"}</ul></div></div><div class="pr-callout"><b>다음 90일 초점:</b> ${dl.next.map(esc).join(" / ")}</div>`,total)}
  html+=prPage(pg(),'Methodology & Data Quality',`<div class="pr-kicker">Methodology & Evidence</div><h2 class="pr-h2">진단 방법론·데이터 품질</h2><p class="pr-lead">기술수준과 근거수준을 분리하고, 핵심기술 단위 TRL·7개 역량영역·Evidence Confidence를 결합합니다.</p><div class="pr-flow"><div><b>1. Technology Discovery</b><p>사업언어에서 제품·데이터·알고리즘·공정·의존요소를 추출</p></div><div><b>2. Critical Technology</b><p>제품성과를 좌우하는 핵심기술을 선별하고 TRL 확인</p></div><div><b>3. Evidence-aware Assessment</b><p>12개 Core + 산업심화문항, 모름은 0점이 아닌 불확실성</p></div><div><b>4. Action Roadmap</b><p>Gap → 우선순위 → KPI → Evidence → 재진단</p></div></div><div class="pr-divider"></div><div class="pr-grid4">${prMetric('응답완료',complete,'문항 완료율')}${prMetric('근거강도',evAvg,'Evidence 평균')}${prMetric('기술확인',confirm,'기업 확인율')}${prMetric("'모름' 응답",r.unknown,`${activeQs().length}문항 중`)}</div><div class="pr-grid2" style="margin-top:3mm"><div class="pr-card"><h4>평가원칙</h4><ul><li>기업규모·직원수·업력은 직접 가점하지 않음</li><li>TRL은 기술성숙도이며 기업가치·시장성 점수가 아님</li><li>자가진술과 외부검증을 별도 Confidence로 관리</li><li>로드맵 포함 여부는 기술우수성·선정가능성을 의미하지 않음</li></ul></div><div class="pr-card warn"><h4>현재 검증상태</h4><p>문항·가중치·우선순위는 POC 단계입니다. 정식 서비스 전 전문가 내용타당도(CVI/CVR), Cognitive Interview, 기업 Pilot, 신뢰도·수렴타당도, 업종별 Calibration이 필요합니다.</p></div></div>`,total);

  html+=prPage(pg(),'Scorecard',`<div class="pr-kicker">Capability Scorecard</div><h2 class="pr-h2">7개 영역 종합 Scorecard</h2><div class="pr-grid2"><div class="pr-card pr-radar"><h4>7개 영역 프로파일</h4>${radarSVG(r.m)}</div><div class="pr-card soft">${prBars(r)}<h4 style="margin-top:3mm">Scorecard 해석</h4><p>${dims.weak[0][1]===null?"응답이 부족해 영역별 점수를 산정하지 않았습니다. 핵심 문항 응답과 담당자 확인 후 재진단하면 강점·병목을 제시합니다.":`가장 낮은 영역은 <b>${dims.weak[0][0]}</b> ${fmtScore(dims.weak[0][1])}이며, 가장 높은 영역은 <b>${dims.strong[0][0]}</b> ${fmtScore(dims.strong[0][1])}입니다. 병목영역을 우선 개선하지 않으면 강점영역의 투자효과도 제한될 수 있습니다.`}</p><div class="pr-callout"><b>우선순위 원칙:</b> Gap 크기 + 리스크 + 낮은 Confidence + 전략정렬 필요성을 함께 고려합니다.</div></div></div><div class="pr-divider"></div><table class="pr-table"><thead><tr><th style="width:19%">영역</th><th style="width:11%">점수</th><th style="width:17%">상태</th><th>핵심 해석</th></tr></thead><tbody>${areas.map(x=>`<tr data-ckrow="area" data-area="${x[0]}" data-score="${x[1]===null?'':Math.round(x[1])}"><td><b>${x[0]}</b></td><td>${fmtScore(x[1])}</td><td>${band(x[1])}</td><td>${dimensionDetail(x[0],x[1]).interpret}${x[1]===null?'':driverLine(x[0],'pr-source',1)}</td></tr>`).join('')}</tbody></table>`,total);

  const weakDetails=dims.weak.map(x=>({name:x[0],score:x[1],d:dimensionDetail(x[0],x[1])}));
  html+=prPage(pg(),'Deep Diagnosis',`<div class="pr-kicker">Deep Diagnosis</div><h2 class="pr-h2">핵심 병목·근본원인 가설</h2><p class="pr-lead">아래 원인은 확정판정이 아니라 응답패턴에 근거한 검증가설입니다. 인터뷰·문서·현장데이터로 확인해야 합니다.</p><div class="pr-grid3">${weakDetails.map(x=>`<div class="pr-card ${x.score<45?'bad':'warn'}"><h4>${x.name} · ${Math.round(x.score)}/100</h4><p><b>해석</b> ${x.d.interpret}</p>${driverLine(x.name,'pr-source')}<ul>${x.d.improve.map(z=>`<li>${z}</li>`).join('')}</ul><p style="margin-top:2mm"><b>KPI</b> ${x.d.kpi}</p></div>`).join('')}</div><div class="pr-divider"></div><div class="pr-grid2">${aiOk()&&aiState.data.interpretation.root_cause_hypotheses.length?`<div class="pr-card"><h4>근본원인 가설 <span class="pr-source">AI 해석(Claude) · 검증 전</span></h4><ul>${aiState.data.interpretation.root_cause_hypotheses.map(h=>`<li>${esc(prClip(h.text,95))} <span class="pr-source">확인: ${esc(prClip(h.verify_by,36))}</span></li>`).join("")}</ul></div>`:`<div class="pr-card"><h4>근본원인 가설 <span class="pr-source">응답 패턴 기반 · 검증 전</span></h4><ul>${byPriority(r.gaps).slice(0,3).map(g=>{const d=driversOf(g.area)[0];return `<li><b>${g.area}</b>: ${rootCause(g.area)}${d?` <span class="pr-source">근거: ${esc(d.text)}</span>`:''}</li>`}).join('')}</ul></div>`}${aiOk()&&aiState.data.interpretation.confirmation_needed.length?`<div class="pr-card soft"><h4>추가 확인 질문 <span class="pr-source">AI 해석(Claude)</span></h4><ul>${aiState.data.interpretation.confirmation_needed.map(q=>`<li>${esc(prClip(q,95))}</li>`).join("")}</ul></div>`:`<div class="pr-card soft"><h4>추가 확인 질문 <span class="pr-source">응답에서 생성</span></h4><ul>${(fq=>fq.length?fq.map(q=>`<li>${esc(q)}</li>`).join(''):'<li>현재 P0 기술과제의 담당자와 완료기준이 문서화되어 있는가?</li><li>핵심기술별 최신 시험결과와 실패원인을 다시 찾을 수 있는가?</li>')(fallbackQuestions(r))}</ul></div>`}</div>`,total);

  html+=prPage(pg(),'Critical Technology & TRL',`<div class="pr-kicker">Critical Technology</div><h2 class="pr-h2">핵심기술별 TRL·다음 Gate</h2><p class="pr-lead">기업 전체에 TRL 하나를 부여하지 않고, 핵심기술별 현재 상태와 다음 검증 Gate를 관리합니다.</p><table class="pr-table compact pr-rank"><thead><tr><th style="width:5%">순위</th><th style="width:19%">핵심기술</th><th style="width:7%">보유</th><th style="width:12%">TRL 현재→다음</th><th style="width:14%">다음 검증 관문</th><th style="width:24%">확인 항목</th><th>결과 연결</th></tr></thead><tbody>${(ps=>crit.slice(0,6).map(t=>`<tr data-ckrow="rank" data-tech="${esc(t.name)}" data-rnd="${esc(ps.filter(p=>p.techName===t.name).map(p=>p.id).join(','))}"><td><b>${t.rank}</b></td><td><b>${esc(prClip(t.name,28))}</b></td><td>${esc(t.ownership)}</td><td>${t.trl?`TRL ${t.trl}`:'확인 필요'} → ${t.target}</td><td>${t.gate}</td><td><b>${t.row.met}/5</b> ${ckChips(t.row)}</td><td>${esc(prClip(techUse(t.row,ps),60))}</td></tr>`).join('')||`<tr><td colspan="7">핵심기술을 먼저 지정해야 합니다(3단계 '핵심기술' 체크).</td></tr>`)(r.insufficient?[]:rndNow(r))}</tbody></table><p class="pr-source" style="margin-top:1.5mm">${RANK_RULE} 확인 항목: 차별=경쟁사가 따라 하기 어려운 부분 답변과 연결 · 로드맵=이름이 겹치는 로드맵 품목 있음 · 자체=자체·혼합 보유 · TRL=TRL 입력 · 확인=기업 확인. ?는 정보 없음.${crit.length>6?` 핵심기술 ${crit.length}건 중 상위 6건만 표시.`:''}</p>${excludedNote()?`<p class="pr-source">${excludedNote()}</p>`:''}<div class="pr-divider"></div><div class="pr-grid2"><div class="pr-card soft"><h4>Technology Fingerprint</h4><p><b>제품/서비스</b> ${esc(state.company.product||'미입력')}</p><p style="margin-top:1.5mm"><b>핵심 차별요소</b> ${esc(state.discovery.hardPart||'미입력')}</p><p style="margin-top:1.5mm"><b>데이터</b> ${esc(state.discovery.data||'미입력')}</p></div><div class="pr-card"><h4>TRL 운영원칙</h4><ul><li>TRL 상승은 다음 Gate를 통과한 근거가 있을 때만 인정</li><li>기술성숙도와 R&D 역량·사업성·시장성은 별도 관리</li><li>TRL 7 이상은 실제환경/운영 Evidence를 우선 요구</li><li>권고 근거자료: TRL 6 이하 시험기록·PoC·성능지표·개선이력, TRL 7 이상 실사용 성능·운영로그·고객 검증</li></ul></div></div>`,total);

  const rndP=r.insufficient?[]:rndNow(r);
  html+=prPage(pg(),'Strategic Alignment',`<div class="pr-kicker">Strategic Alignment</div><h2 class="pr-h2">기술로드맵 정렬(참고 후보)·정책 연계</h2><p class="pr-lead">공식 로드맵 원문 색인에서 입력 내용과 단어가 겹치는 전략품목입니다. 키워드 일치 순서이며 적합도 판정이 아니므로 원문 해당 쪽 확인이 필요합니다.</p><div class="pr-grid3">${matches.map((m,i)=>`<div class="pr-card ${i===0?'soft':''}"><span class="pr-pill">후보 ${i+1}${m.weak?' · 약한 후보':''}</span><h4 style="margin-top:1.5mm">${esc(m.name)}</h4><p>${itemId(m)}${m.page?` · 원문 p.${m.page}`:''}</p>${(m.matchedTechs||[]).length?`<ul>${m.matchedTechs.map(t=>`<li>${esc(t.name)}${t.trl?` (TRL ${esc(t.trl)})`:''}</li>`).join('')}</ul>`:''}${(rmEvidence.items[m.uid]||[]).slice(0,1).map(e=>`<p class="pr-quote">“${esc(e.quote.length>90?e.quote.slice(0,90)+'…':e.quote)}” <span class="pr-source">원문 p.${e.printedPage??'?'}</span></p>`).join('')}<div class="pr-source">${esc(m.source)} · ${m.label}</div></div>`).join('')}</div><div class="pr-divider"></div><table class="pr-table"><thead><tr><th>기업 핵심기술</th><th>로드맵 후보</th><th>연결된 R&D 과제</th><th>추가 검증</th></tr></thead><tbody>${crit.slice(0,4).map((t,i)=>`<tr data-ckrow="rm" data-tech="${esc(t.name)}"><td><b>${esc(t.name)}</b></td><td>${(c=>c?`${esc(c.name)}<br><span class="pr-source">${itemId(c)}${c.page?` · p.${c.page}`:''}</span>`:'이름 일치 품목 없음 — 원문 검토 필요')(techCandidate(t))}</td><td>${(ids=>ids.length?esc(ids.join(' · ')):'대조표 작성 대상')(rndP.filter(p=>p.techName===t.name).map(p=>`${p.id} ${p.trackLabel}`))}</td><td>${(c=>c&&c.page?`원문 p.${c.page} 개발목표·TRL과 대조`:'원문 전략품목·개발목표 확인')(techCandidate(t))}</td></tr>`).join('')}</tbody></table>${crit.length>4?`<div class="pr-source">※ 핵심기술 ${crit.length}건 중 4건만 표시했습니다.</div>`:''}<div class="pr-callout">${rmCallout()}</div>`,total);

  {const cs=r.insufficient?[]:gapNow(r),note=t=>{const x=aiInt(),n=x&&(x.gap_notes||[]).find(o=>o.tech===t);return n?`<tr class="pr-subrow"><td colspan="4"><span class="pr-source">AI 메모</span> ${esc(prClip(n.why,100))} <span class="pr-source">첫 단계: ${esc(prClip(n.first_step,60))}</span></td></tr>`:""};html+=prPage(pg(),'보완 필요 기술',`<div class="pr-kicker">보완 필요</div><h2 class="pr-h2">보완 필요 기술·데이터</h2><p class="pr-lead">로드맵 후보 품목의 원문 핵심기술 전체를 자사 핵심기술과 이름으로 대조했습니다. 원문 TRL은 품목 기준값(대조 기준)이며 적합도·선정 가능성이 아닙니다.</p>${cs.length?cs.map(c=>`<div class="pr-card pr-gap"><h4>${esc(c.item.name)} <span class="pr-source">${c.item.code?esc(c.item.code):""}${c.item.page?` · 원문 p.${c.item.page}`:""}</span></h4><table class="pr-table compact"><thead><tr><th style="width:38%">원문 핵심기술</th><th style="width:13%">원문 TRL·쪽</th><th style="width:17%">판단</th><th>근거·보완 경로</th></tr></thead><tbody>${c.rows.slice(0,6).map(g=>`<tr data-ckrow="gapt" data-status="${g.status}" data-company="${g.company?esc(g.company.name):''}"><td><b>${esc(prClip(g.roadmapTech,44))}</b></td><td>${g.trlRef?`TRL ${esc(g.trlRef)}`:"—"}${g.page?` · p.${g.page}`:""}</td><td><span class="pr-pill ${gapCls(g.status)==="ok"?"ok":gapCls(g.status)==="info"?"":"warn"}">${GAP_STATUS_LABEL[g.status]}</span></td><td>${gapBasis(g)}</td></tr>${g.status==="gap"||g.status==="mentioned"?note(g.roadmapTech):""}`).join("")}</tbody></table><p class="pr-source" style="margin-top:1mm">${c.dataUnchecked?"데이터 답변이 비어 데이터는 대조하지 않았습니다.":c.dataGaps.length?`보완 필요 데이터 후보: ${c.dataGaps.map(d=>`${esc(d.term)} 데이터(원문 '${esc(prClip(d.roadmapTech,30))}'${d.page?` p.${d.page}`:""})`).join(" / ")}`:"원문 핵심기술에 나오는 데이터 종류는 모두 데이터 답변에 있습니다."}</p></div>`).join(""):`<div class="pr-card">${r.insufficient?"응답이 부족해 대조하지 않았습니다(판단 보류).":"로드맵 후보에 원문 핵심기술 목록이 없어 대조하지 않았습니다."}</div>`}<div class="pr-callout"><b>쓰는 법:</b> '보완 필요 후보'는 자체 개발할지 공동R&D·기술 도입으로 채울지 정할 대상입니다. 이름 겹침만으로 판단하므로 원문 해당 쪽의 개발목표와 대조한 뒤 R&D 과제·90일 계획에 반영하세요.</div>`,total)}
  html+=prPage(pg(),'Gap & Root Cause',`<div class="pr-kicker">Gap Intelligence</div><h2 class="pr-h2">기술 Gap·원인·개선방향</h2><table class="pr-table"><thead><tr><th style="width:15%">우선</th><th style="width:18%">영역</th><th style="width:11%">현재</th><th style="width:25%">Gap 해석</th><th>개선방향</th></tr></thead><tbody>${byPriority(r.gaps).map(g=>{let d=dimensionDetail(g.area,g.score);return`<tr data-ckrow="gap" data-area="${g.area}" data-pri="${g.priority}"><td><span class="pr-pill ${g.priority==='P0'?'bad':g.priority==='P1'?'warn':'ok'}">${g.priority}</span></td><td><b>${g.area}</b></td><td>${fmtScore(g.score)}</td><td>${gapText(g.area,g.score)}</td><td>${d.improve.slice(0,2).join(' / ')}</td></tr>`}).join('')}</tbody></table><div class="pr-divider"></div><div class="pr-grid2"><div class="pr-card"><h4>원인 → 결과 연결</h4><ul>${byPriority(r.gaps).slice(0,3).map(g=>{let d=dimensionDetail(g.area,g.score);return`<li><b>[${g.priority}] ${g.area}</b>: ${d.interpret} → ${josa(plainKo(actionText(g.area)[0]),'이','가')} 90일 우선과제</li>`}).join('')}</ul></div><div class="pr-card warn"><h4>의사결정 리스크 <span class="pr-source" data-ck="ref" data-to="risk">레드팀 상위 4 · {{P:risk}}쪽</span></h4><ul>${risks.slice(0,4).map(x=>`<li><b>${x.id} ${esc(x.name)}</b> (${x.grade}) - ${esc(x.scenario)}</li>`).join('')}</ul></div></div>`,total);

  html+=prPage(pg(),'Strategic Options',`<div class="pr-kicker">Strategic Options</div><h2 class="pr-h2">전략 대안 비교</h2><p class="pr-lead">현재 상태에서 가능한 3개 경로를 비교하고, 실행 전제와 Trade-off를 함께 제시합니다.</p><div class="pr-grid3">${opts.map(o=>`<div class="pr-card pr-option ${o.recommended?'recommended':''}"><div class="opt-head"><b>${o.name}</b><span class="opt-score">${o.recommended?'우선 검토':'대안'}</span></div><div class="pr-optbar"><div class="pr-bar"><i style="width:${o.score??0}%"></i></div><span>${o.score===null?'산정 불가':`기준 점수 ${o.score}`}</span></div><p><b>적합 상황</b> ${o.when}</p><p style="margin-top:1.5mm"><b>핵심 Focus</b> ${o.focus}</p><p style="margin-top:1.5mm"><b>Trade-off</b> ${o.trade}</p>${(n=>n?`<p class="pr-ai-line"><span class="pr-source">이 기업 맥락 · AI</span> ${esc(prClip(n.text,110))}<br><span class="pr-source">실행 전제: ${esc(prClip(n.prerequisite,60))}</span></p>`:'')(aiOpt(o.name.charAt(0)))}</div>`).join('')}</div><p class="pr-source" style="margin-top:-1mm">${esc(recommendReason(r))}${aiOk()?' AI 메모는 추천안을 바꾸지 않습니다.':''}</p><div class="pr-callout" data-ck="rec" data-v="${opts.find(o=>o.recommended).name}"><b>우선 검토안:</b> ${opts.find(o=>o.recommended).name}. 이는 현재 진단점수와 Evidence 수준을 기반으로 한 POC 의사결정 가이드이며, 실제 투자·예산 결정 전 비용·인력·고객일정을 추가 검증해야 합니다.</div><div class="pr-grid2"><div class="pr-card"><h4>대안 선택 기준</h4><ul><li>기술성숙도와 Evidence Confidence의 균형</li><li>90일 내 검증 가능한가?</li><li>핵심고객·시장진입과 직접 연결되는가?</li><li>외부의존·규제·인력 리스크를 감당할 수 있는가?</li></ul></div><div class="pr-card"><h4>추가 의사결정 데이터</h4><ul>${decisionData(PLAN||planCtx(r)).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div>`,total);

  {const ps=r.insufficient?[]:rndNow(r);html+=prPage(pg(),'R&D Proposals',`<div class="pr-kicker">R&D 과제 제안</div><h2 class="pr-h2">R&D 과제(지원사업) 기술 제안</h2><p class="pr-lead">진단 결과·핵심기술 TRL·공식 로드맵 원문 후보로 만든 과제 기획 초안입니다. 목표 TRL은 2~3년 과제 기준 제안값이며 정량 목표·예산·기간은 기업이 정합니다.</p>${ps.length?ps.map(p=>`<div class="pr-card pr-rnd" data-ckrow="rnd" data-id="${p.id}" data-tech="${esc(p.techName)}"><div class="pr-rnd-head"><span class="pr-pill">${p.trackLabel}</span><span class="pr-pill ${rdCls(p.readiness)}">${p.readiness}</span><b>${esc(prClip(p.title,48))}</b></div><div class="pr-rnd-body"><div><p><b>연계 기술</b> ${esc(prClip(p.techName,30))} · ${p.trlNow?`TRL ${p.trlNow}`:"TRL 확인 필요"} → ${esc(p.trlTarget)}</p><p><b>로드맵 연계</b> ${esc(prClip(rmText(p.roadmap),80))}</p><p><b>제안 근거</b> ${esc(prClip(p.why,110))}</p>${(n=>n?`<p class="pr-ai-line"><span class="pr-source">과제명 제안 · AI</span> ${esc(prClip(n.title,50))} — ${esc(prClip(n.summary,90))}</p>`:"")(aiInt()&&(aiInt().rnd_notes||[]).find(o=>o.id===p.id))}</div><div><p><b>주요 개발 내용</b></p><ul>${p.contents.map(c=>`<li>${esc(c)}</li>`).join("")}</ul><p style="margin-top:1mm"><b>신청 전 준비</b></p><ul>${p.prep.slice(0,3).map(c=>`<li>${esc(c)}</li>`).join("")||"<li>공고 요건 확인</li>"}</ul></div></div></div>`).join(""):`<div class="pr-card">${r.insufficient?"응답이 부족해 과제 제안을 만들지 않았습니다(판단 보류).":"핵심기술을 지정하고 TRL을 확인하면 과제 제안을 만듭니다."}</div>`}<div class="pr-callout"><b>확인할 점:</b> 지원사업 선정 가능성을 뜻하지 않습니다. 공고별 신청 자격(기업 규모·업력·매칭 비율·중복 지원 제한)과 평가 기준, 로드맵 원문 개발목표를 반드시 대조하세요.</div>`,total)}
  {const R0=readyNow(),pn=a=>{const x=aiInt(),n=x&&(x.plan_notes||[]).find(o=>o.axis===a);return n?`<p class="pr-ai-line"><span class="pr-source">작성 포인트 · AI</span> ${esc(prClip(n.point,80))}</p>`:""};html+=prPage(pg(),'Readiness',`<div class="pr-kicker">신청 준비도</div><h2 class="pr-h2">지원사업 신청 준비도(R&D·기술바우처)</h2><p class="pr-lead">신청 전에 보완할 점을 진단 근거로 정리했습니다. 선정 가능성이 아니라 '신청 전 보완 진단'이며 관점·판정 기준은 시범 기준입니다.</p><div class="pr-callout" data-ck="ready" data-overall="${R0.overall}"><b>종합 · ${R0.overall}</b> — ${esc(R0.reason)}</div><div class="pr-grid2 pr-ready">${R0.axes.map(a=>`<div class="pr-card" data-ckrow="axis" data-status="${a.status}"><h4>${a.label} <span class="pr-pill ${rsCls(a.status)}">${a.status}</span></h4>${a.evidence.length?`<p class="pr-source">${esc(prClip(a.evidence.join(" · "),120))}</p>`:""}<p>${esc(prClip(a.comment,120))}</p>${a.actions.length&&a.status!=="충족"?`<p class="pr-source"><b>신청 전 할 일</b> ${esc(prClip(a.actions.join(" · "),80))}</p>`:""}${pn(a.label)}</div>`).join("")}</div><div class="pr-grid2"><div class="pr-card"><h4>기술바우처 활용 후보 <span class="pr-source">자부담·중복 지원은 공고 확인</span></h4>${R0.vouchers.length?`<table class="pr-table compact"><tbody>${R0.vouchers.map(v=>`<tr data-ckrow="voucher" data-risk="${v.riskId||""}"><td style="width:28%"><b>${v.type}</b></td><td>${esc(prClip(v.why,60))}<br><span class="pr-source">${esc(prClip(v.effect,50))}</span></td></tr>`).join("")}</tbody></table>`:"<p>진단 근거상 바우처로 메울 뚜렷한 약점이 없습니다.</p>"}</div><div class="pr-card"><h4>공통 자격 확인 <span class="pr-source">${R0.eligAnswered?`${R0.eligAnswered}/8 입력`:"1단계 자격 확인 입력 전"}</span></h4><div class="pr-elig">${R0.eligibility.map(e=>`<div data-ckrow="elig" data-status="${e.status}"><span>${esc(e.label.replace(/\(.*\)/,""))}</span><span class="pr-pill ${rsCls(e.status)}">${e.status}</span></div>`).join("")}</div></div></div>`,total)}
