function autoSave(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}catch{}}
function render(){seedInv();document.querySelectorAll(".section").forEach((e,i)=>e.classList.toggle("active",i===state.step));nav();basic();discovery();inv();diagnosis();evidence();if(state.step===5||state.results){result();buildPrintReport()}autoSave()}
function saveState(){syncBasic();syncDiscovery();localStorage.setItem(STORAGE_KEY,JSON.stringify(state));alert("현재 상태를 저장했습니다.")}
function loadState(){try{let s=localStorage.getItem(STORAGE_KEY);if(s){let o=JSON.parse(s);state={...fresh(),...o,company:{...fresh().company,...o.company},discovery:{...fresh().discovery,...o.discovery}}}}catch(e){state=fresh()}}
function resetState(){if(confirm("현재 입력을 초기화할까요?")){localStorage.removeItem(STORAGE_KEY);state=fresh();render();navTo(0)}}
